window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5a42bed8f780784b"]={"versions": [{"id": "FIG-5a42bed8f780784b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Meta-Modell-Ausschnitt) der AUTOSAR Adaptive und Classic Platform (TPS Security Extract Template). Das Diagramm spezifiziert die primäre Modellstruktur zur Konfiguration und Zuordnung von Intrusion Detection System (Ids)-Elementen und Security-Event-Kontexten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>:\n<ul class=\"fig-list\"><li><code>IdsDesign</code>: Konkretes Wurzelelement / Container, aggregiert über die gerichtete Komposition <code>+element</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen der abstrakten Klasse <code>IdsCommonElement</code>.\n</li><li><code>IdsCommonElement</code>: Abstrakte Basisklasse (spezialisiert <code>ARElement</code>), von der abgeleitet sind:\n<ul class=\"fig-list\"><li><code>SecurityEventDefinition</code>\n</li><li><code>IdsmProperties</code>\n</li><li><code>SecurityEventFilterChain</code>\n</li><li><code>IdsmInstance</code>\n</li><li><code>IdsMapping</code> (abstrakte Basisklasse für Mappings)\n</li></ul>\n</li></ul>\n</li><li><strong>IdsMapping &amp; SecurityEventContextMapping</strong>:\n<ul class=\"fig-list\"><li><code>IdsMapping</code>: Abstrakte Basisklasse, spezialisiert <code>IdsCommonElement</code>.\n</li><li><code>SecurityEventContextMapping</code>: Abstrakte Spezialisierung von <code>IdsMapping</code>.\n</li><li>Konkrete Spezialisierungen von <code>SecurityEventContextMapping</code>:\n<ul class=\"fig-list\"><li><code>SecurityEventContextMappingBswModule</code>: Kontextzuordnung zu BSW-Modulen (Classic Platform).\n</li><li><code>SecurityEventContextMappingFunctionalCluster</code>: Kontextzuordnung zu Functional Clustern (Adaptive Platform).\n</li><li><code>SecurityEventContextMappingCommConnector</code>: Kontextzuordnung zu Kommunikations-Konnektoren.\n</li><li><code>SecurityEventContextMappingApplication</code>: Kontextzuordnung zu Applikationsebene / SWCs.\n</li></ul>\n</li></ul>\n</li><li><strong>Assoziationen von <code>SecurityEventContextMapping</code></strong>:\n<ul class=\"fig-list\"><li><code>+idsmInstance</code>: Gerichtete Assoziation zu <code>IdsmInstance</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation»</code>).\n</li><li><code>+filterChain</code>: Gerichtete Assoziation zu <code>SecurityEventFilterChain</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Meta-Modell ohne dynamische Laufzeitsequenzen. Die Struktur definiert statische Entwurfsmuster für die Aggregation (<code>IdsDesign</code> fasst Security-Elemente zusammen) sowie die Konfiguration von Überwachungskontexten, bei denen Security-Events über <code>SecurityEventContextMapping</code> wahlweise an eine Filterkette (<code>SecurityEventFilterChain</code>) und eine IdsM-Instanz (<code>IdsmInstance</code>) gebunden werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Variabilitäts- und Split-Mechanismen</strong>:\n<ul class=\"fig-list\"><li>Die Komposition <code>IdsDesign.element</code> ist als <code>«atpVariation,atpSplitable»</code> deklariert; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>idsmInstance</code> trägt <code>«atpVariation»</code>; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>filterChain</code> trägt <code>«atpVariation»</code>; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong>Implementierungshinweise</strong>:\n<ul class=\"fig-list\"><li>Die vier Spezialisierungen von <code>SecurityEventContextMapping</code> stellen sicher, dass Security-Ereignisse architekturübergreifend sowohl in der Classic Platform (BSW) als auch in der Adaptive Platform (Functional Cluster) sowie über Kommunikations- und Applikationsgrenzen hinweg typisiert zugeordnet werden können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7a99a6650bdbbe02", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Meta-Modell-Ausschnitt) der AUTOSAR Adaptive und Classic Platform (TPS Security Extract Template). Das Diagramm spezifiziert die primäre Modellstruktur zur Konfiguration und Zuordnung von Intrusion Detection System (Ids)-Elementen und Security-Event-Kontexten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>:\n<ul class=\"fig-list\"><li><code>IdsDesign</code>: Konkretes Wurzelelement / Container, aggregiert über die gerichtete Komposition <code>+element</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen der abstrakten Klasse <code>IdsCommonElement</code>.\n</li><li><code>IdsCommonElement</code>: Abstrakte Basisklasse (spezialisiert <code>ARElement</code>), von der abgeleitet sind:\n<ul class=\"fig-list\"><li><code>SecurityEventDefinition</code>\n</li><li><code>IdsmProperties</code>\n</li><li><code>SecurityEventFilterChain</code>\n</li><li><code>IdsmInstance</code>\n</li><li><code>IdsMapping</code> (abstrakte Basisklasse für Mappings)\n</li></ul>\n</li></ul>\n</li><li><strong>IdsMapping &amp; SecurityEventContextMapping</strong>:\n<ul class=\"fig-list\"><li><code>IdsMapping</code>: Abstrakte Basisklasse, spezialisiert <code>IdsCommonElement</code>.\n</li><li><code>SecurityEventContextMapping</code>: Abstrakte Spezialisierung von <code>IdsMapping</code>.\n</li><li>Konkrete Spezialisierungen von <code>SecurityEventContextMapping</code>:\n<ul class=\"fig-list\"><li><code>SecurityEventContextMappingBswModule</code>: Kontextzuordnung zu BSW-Modulen (Classic Platform).\n</li><li><code>SecurityEventContextMappingFunctionalCluster</code>: Kontextzuordnung zu Functional Clustern (Adaptive Platform).\n</li><li><code>SecurityEventContextMappingCommConnector</code>: Kontextzuordnung zu Kommunikations-Konnektoren.\n</li><li><code>SecurityEventContextMappingApplication</code>: Kontextzuordnung zu Applikationsebene / SWCs.\n</li></ul>\n</li></ul>\n</li><li><strong>Assoziationen von <code>SecurityEventContextMapping</code></strong>:\n<ul class=\"fig-list\"><li><code>+idsmInstance</code>: Gerichtete Assoziation zu <code>IdsmInstance</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation»</code>).\n</li><li><code>+filterChain</code>: Gerichtete Assoziation zu <code>SecurityEventFilterChain</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Meta-Modell ohne dynamische Laufzeitsequenzen. Die Struktur definiert statische Entwurfsmuster für die Aggregation (<code>IdsDesign</code> fasst Security-Elemente zusammen) sowie die Konfiguration von Überwachungskontexten, bei denen Security-Events über <code>SecurityEventContextMapping</code> wahlweise an eine Filterkette (<code>SecurityEventFilterChain</code>) und eine IdsM-Instanz (<code>IdsmInstance</code>) gebunden werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Variabilitäts- und Split-Mechanismen</strong>:\n<ul class=\"fig-list\"><li>Die Komposition <code>IdsDesign.element</code> ist als <code>«atpVariation,atpSplitable»</code> deklariert; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>idsmInstance</code> trägt <code>«atpVariation»</code>; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>filterChain</code> trägt <code>«atpVariation»</code>; Tag <code>atp.Status = draft</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong>Implementierungshinweise</strong>:\n<ul class=\"fig-list\"><li>Die vier Spezialisierungen von <code>SecurityEventContextMapping</code> stellen sicher, dass Security-Ereignisse architekturübergreifend sowohl in der Classic Platform (BSW) als auch in der Adaptive Platform (Functional Cluster) sowie über Kommunikations- und Applikationsgrenzen hinweg typisiert zugeordnet werden können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7e65890025ac763e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Meta-Modell-Ausschnitt) der AUTOSAR Adaptive und Classic Platform (TPS Security Extract Template). Das Diagramm spezifiziert die primäre Modellstruktur zur Konfiguration und Zuordnung von Intrusion Detection System (Ids)-Elementen und Security-Event-Kontexten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>:\n<ul class=\"fig-list\"><li><code>IdsDesign</code>: Konkretes Wurzelelement / Container, aggregiert über die gerichtete Komposition <code>+element</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen der abstrakten Klasse <code>IdsCommonElement</code>.\n</li><li><code>IdsCommonElement</code>: Abstrakte Basisklasse (spezialisiert <code>ARElement</code>), von der abgeleitet sind:\n<ul class=\"fig-list\"><li><code>SecurityEventDefinition</code>\n</li><li><code>IdsmProperties</code>\n</li><li><code>SecurityEventFilterChain</code>\n</li><li><code>IdsmInstance</code>\n</li><li><code>IdsMapping</code> (abstrakte Basisklasse für Mappings)\n</li></ul>\n</li></ul>\n</li><li><strong>IdsMapping &amp; SecurityEventContextMapping</strong>:\n<ul class=\"fig-list\"><li><code>IdsMapping</code>: Abstrakte Basisklasse, spezialisiert <code>IdsCommonElement</code>.\n</li><li><code>SecurityEventContextMapping</code>: Abstrakte Spezialisierung von <code>IdsMapping</code>.\n</li><li>Konkrete Spezialisierungen von <code>SecurityEventContextMapping</code>:\n<ul class=\"fig-list\"><li><code>SecurityEventContextMappingBswModule</code>: Kontextzuordnung zu BSW-Modulen (Classic Platform).\n</li><li><code>SecurityEventContextMappingFunctionalCluster</code>: Kontextzuordnung zu Functional Clustern (Adaptive Platform).\n</li><li><code>SecurityEventContextMappingCommConnector</code>: Kontextzuordnung zu Kommunikations-Konnektoren.\n</li><li><code>SecurityEventContextMappingApplication</code>: Kontextzuordnung zu Applikationsebene / SWCs.\n</li></ul>\n</li></ul>\n</li><li><strong>Assoziationen von <code>SecurityEventContextMapping</code></strong>:\n<ul class=\"fig-list\"><li><code>+idsmInstance</code>: Gerichtete Assoziation zu <code>IdsmInstance</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>).\n</li><li><code>+filterChain</code>: Gerichtete Assoziation zu <code>SecurityEventFilterChain</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Meta-Modell ohne dynamische Laufzeitsequenzen. Die Struktur definiert statische Entwurfsmuster für die Aggregation (<code>IdsDesign</code> fasst Security-Elemente zusammen) sowie die Konfiguration von Überwachungskontexten, bei denen Security-Events über <code>SecurityEventContextMapping</code> wahlweise an eine Filterkette (<code>SecurityEventFilterChain</code>) und eine IdsM-Instanz (<code>IdsmInstance</code>) gebunden werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Variabilitäts- und Split-Mechanismen</strong>:\n<ul class=\"fig-list\"><li>Die Komposition <code>IdsDesign.element</code> ist als <code>«atpVariation,atpSplitable»</code> deklariert; Tag <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>idsmInstance</code> trägt <code>«atpVariation,atpSplitable»</code>; Tag <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = systemDesignTime</code>.\n</li><li>Die Assoziation <code>filterChain</code> trägt <code>«atpVariation,atpSplitable»</code>; Tag <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong>Implementierungshinweise</strong>:\n<ul class=\"fig-list\"><li>Die Hinzunahme des Stereotyps <code>«atpSplitable»</code> an <code>idsmInstance</code> und <code>filterChain</code> erlaubt das Splitten dieser Zuordnungen über mehrere ARXML-Dateifragmente hinweg.\n</li><li>Der Reifegradstatus (<code>atp.Status</code>) aller modellierten Variationspunkte wurde von Entwurfsstatus (<code>draft</code>) auf Reifegrad <code>candidate</code> angehoben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5a42bed8f780784b", "to": "FIG-7a99a6650bdbbe02", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7a99a6650bdbbe02", "to": "FIG-7e65890025ac763e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SecurityEventContextMapping.idsmInstance</code>: Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li><li><code>SecurityEventContextMapping.filterChain</code>: Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li><li><code>«atpVariation» Tags</code>: Tag <code>atp.Status</code> für <code>IdsDesign.element</code>, <code>idsmInstance</code> und <code>filterChain</code> jeweils von <code>draft</code> auf <code>candidate</code> hochgestuft.\n</li></ul>"}]};
